(function() {
  const body = document.body;
  const oldSize = getComputedStyle(body).fontSize;
  body.style.fontSize = '24px';
  return { old: oldSize, new: body.style.fontSize };
})();

(() => {
  const entries = [];
  for (let i = 0; i < window.history.length; i++) {
    try {
      entries.push({ index: i, url: window.history[i].url });
    } catch (e) {}
  }
  return JSON.stringify({ length: window.history.length, entries });
})()

